  f: [["ETEC", "Enterotoxigenic E. coli"], ["STEC", "Shiga toxin producing E. coli"], ["APEC", "Avian pathogenic E. coli"], ["IMViC", "Biochemical test set"], ["Colostrum", "First milk with antibodies"]],
